function freshState(){state=readState();return state;}
function shuffleList(items){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function quizOptions(q,question){let seed=0;for(const c of q.token+question.id)seed=(Math.imul(seed,31)+c.charCodeAt(0))>>>0;const options=[...question.options];for(let i=options.length-1;i>0;i--){seed=(Math.imul(seed,1664525)+1013904223)>>>0;const j=seed%(i+1);[options[i],options[j]]=[options[j],options[i]];}return options;}
function startQuiz(){freshState();if(validateQuiz(state.quiz)&&!state.quiz.awarded){renderQuiz();return;}const previous=new Set(state.quiz?.ids||[]);const ids=shuffleList(QUESTIONS.filter(q=>!previous.has(q.id))).slice(0,QUIZ_LENGTH).map(q=>q.id);state.quiz={ids,answers:[],review:false,awarded:false,token:Date.now().toString(36)+'-'+Math.floor(random()*1e9)};persist();renderQuiz();}
function answerQuiz(choice,expectedToken,expectedIndex){freshState();const q=state.quiz;if(!validateQuiz(q)||q.review||q.awarded||q.answers.length===QUIZ_LENGTH||(expectedToken!=null&&(expectedToken!==q.token||expectedIndex!==q.answers.length)))return false;const question=QUESTIONS.find(x=>x.id===q.ids[q.answers.length]);if(!question.options.includes(choice))return false;q.answers.push(choice);q.review=true;persist();renderQuiz();return true;}
function quizScore(q){return q.answers.reduce((n,a,i)=>n+(QUESTIONS.find(x=>x.id===q.ids[i]).answer===a?1:0),0);}
function advanceQuiz(expectedToken,expectedCount){freshState();const q=state.quiz;if(!validateQuiz(q)||!q.review||q.awarded||(expectedToken!=null&&(expectedToken!==q.token||expectedCount!==q.answers.length)))return false;if(q.answers.length===QUIZ_LENGTH){state.points+=quizScore(q)*POINTS_PER_CORRECT;state.quizzesCompleted++;q.awarded=true;}else q.review=false;persist();stats();renderQuiz();return true;}
function renderQuiz(){const host=$('#quiz-content');const q=state.quiz;$('#quiz-wallet').textContent=state.points.toLocaleString()+' points';if(!validateQuiz(q)){host.innerHTML=`<div class="quiz-welcome"><span class="quiz-emblem">?</span><p class="eyebrow">CURIOSITY PAYS</p><h2>Know a little.<br>Collect a lot.</h2><p>Five questions about history and the people, ideas, economics, and art in your packets.<br>Earn 25 points for every correct answer. A packet costs 100 points.</p><button class="primary" id="start-quiz">Take the test →</button><p class="quiz-note">No timer. No penalty for wrong answers. New questions on every test.</p></div>`;$('#start-quiz').onclick=startQuiz;return;}
 if(q.awarded){const score=quizScore(q),earned=score*POINTS_PER_CORRECT;host.innerHTML=`<div class="quiz-welcome"><span class="quiz-emblem">${score===5?'✳':'✓'}</span><p class="eyebrow">TEST COMPLETE · POINTS SAVED</p><h2>${score} out of ${QUIZ_LENGTH} correct.</h2><p class="earned-points">+${earned} <span>points earned</span></p><p>You have ${state.points.toLocaleString()} points. ${state.points>=PACK_COST?'Your next packet is waiting.':'Take another test to earn enough for a packet.'}</p><div class="quiz-actions"><button class="primary" id="quiz-packs">Open packets →</button><button class="text-link" id="quiz-again">Take another test ↗</button></div><details class="quiz-review"><summary>Review your answers</summary>${q.ids.map((id,i)=>{const question=QUESTIONS.find(x=>x.id===id);return `<article><strong>${i+1}. ${escapeText(question.text)}</strong><p>${q.answers[i]===question.answer?'✓ Correct':'✕ Your answer: '+escapeText(q.answers[i])} · Answer: ${escapeText(question.answer)}</p><p>${escapeText(question.explanation)}</p></article>`;}).join('')}</details></div>`;$('#quiz-packs').onclick=()=>tab('packs');$('#quiz-again').onclick=startQuiz;return;}
 const index=q.review?q.answers.length-1:q.answers.length,question=QUESTIONS.find(x=>x.id===q.ids[index]),selected=q.review?q.answers[index]:null;host.innerHTML=`<div class="question-top"><p class="eyebrow">${escapeText(question.category.toUpperCase())}</p><span>QUESTION ${index+1} / ${QUIZ_LENGTH}</span></div><div class="quiz-meter"><span style="width:${q.answers.length/QUIZ_LENGTH*100}%"></span></div><h2 class="question-title">${escapeText(question.text)}</h2><div class="answer-grid">${quizOptions(q,question).map((option,i)=>`<button class="answer ${q.review?(option===question.answer?'correct':option===selected?'incorrect':''):''}" data-answer="${escapeText(option)}" ${q.review?'disabled':''}><span>${String.fromCharCode(65+i)}</span>${escapeText(option)}${q.review&&option===question.answer?'<b>✓</b>':q.review&&option===selected?'<b>✕</b>':''}</button>`).join('')}</div>${q.review?`<div class="answer-feedback" role="status"><strong>${selected===question.answer?'Correct! +25 points at the end of the test.':'Not quite. The answer is '+escapeText(question.answer)+'.'}</strong><p>${escapeText(question.explanation)}</p><button class="primary" id="next-question">${q.answers.length===QUIZ_LENGTH?'Finish & claim points':'Next question →'}</button></div>`:'<p class="quiz-note">Choose one answer. Points are awarded when you finish all five questions.</p>'}`;
 host.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answerQuiz(b.dataset.answer,q.token,index));if(q.review)$('#next-question').onclick=()=>advanceQuiz(q.token,q.answers.length);
}
$('#earn-button').onclick=()=>tab('quiz');$('#quiz-promo-button').onclick=()=>tab('quiz');renderQuiz();
window.addEventListener('storage',e=>{if(e.key===KEY){freshState();stats();catalog();renderQuiz();}});
